const ctx = $('Init Run Context').first().json;
const mode = (ctx.mode || 'scheduled');
const targetTaskId = (ctx.target_task_id || '').toString().trim();
const tz = (ctx.timezone || 'Europe/Moscow');
const today = $now.setZone(tz).toFormat('yyyy-LL-dd');

// Verify these header names against sheet DAILY_TASKS
const REQUIRED = ['Task_ID','Task_Date','Brand_ID','SKU_ID','Content_Type'];

const rows = $('Read Daily Tasks').all().map(function(i){ return i.json; });
function normDate(v){ if(v===undefined||v===null) return ''; var s=v.toString().trim(); return s.length>=10 ? s.slice(0,10) : s; }

const out = [];
for (var idx=0; idx<rows.length; idx++){
  var r = rows[idx];
  var taskId = (r.Task_ID===undefined||r.Task_ID===null?'':r.Task_ID.toString().trim());
  if(!taskId) continue;
  var status = (r.Task_Status===undefined||r.Task_Status===null?'':r.Task_Status.toString().trim().toUpperCase());
  var taskDate = normDate(r.Task_Date);

  if(mode==='manual'){ if(taskId!==targetTaskId) continue; }
  else { if(taskDate!==today) continue; }
  if(status!=='READY') continue;

  var missing = REQUIRED.filter(function(f){ var val=r[f]; return val===undefined||val===null||val.toString().trim()===''; });

  var parts=[taskId,taskDate,r.Brand_ID,r.SKU_ID,r.Content_Type,r.Channel,r.Audience_ID,r.Brief];
  var hashSource = parts.map(function(x){ return (x===undefined||x===null)?'':x.toString().trim(); }).join('|');
  var h=0; for(var k=0;k<hashSource.length;k++){ h=(h*31+hashSource.charCodeAt(k))|0; }
  var inputHash='H'+(h>>>0).toString(16);

  out.push({ json: Object.assign({}, r, {
    Task_ID: taskId, Task_Date: taskDate, Task_Status: status,
    _mode: mode, _today: today, _timezone: tz,
    Input_Hash: inputHash, _missing_fields: missing,
    task_state: (missing.length ? 'HOLD' : 'PROCESS')
  }) });
}
return out;

const runs = $('Read Runs Log').all().map(function(i){ return i.json; });
const existing = {};
for (var a=0; a<runs.length; a++){
  var rr = runs[a];
  var k = (rr.Task_ID===undefined?'':rr.Task_ID.toString().trim()) + '::' + (rr.Input_Hash===undefined?'':rr.Input_Hash.toString().trim());
  existing[k] = true;
}
const items = $input.all().map(function(i){ return i.json; });
const stamp = $now.toFormat('yyyyLLdd_HHmmss');
const out = [];
for (var b=0; b<items.length; b++){
  var t = items[b];
  var key = t.Task_ID + '::' + t.Input_Hash;
  var isDup = existing[key] === true;
  var runId = 'RUN_' + t.Task_ID + '_' + stamp + '_' + t.Input_Hash;
  out.push({ json: Object.assign({}, t, { Run_ID: runId, dedup_state: (isDup ? 'DUPLICATE' : 'NEW') }) });
}
return out;

const task = $json;
const brandId = (task.Brand_ID===undefined||task.Brand_ID===null?'':task.Brand_ID.toString().trim());
const skuId = (task.SKU_ID===undefined||task.SKU_ID===null?'':task.SKU_ID.toString().trim());
const audId = (task.Audience_ID===undefined||task.Audience_ID===null?'':task.Audience_ID.toString().trim());
const today = (task._today || '');

function arr(name){ return $(name).all().map(function(i){ return i.json; }); }
const brands = arr('Read Brands');
const skus = arr('Read SKUs');
const claims = arr('Read Claims');
const audiences = arr('Read Audiences');
const media = arr('Read Media Library');
const prev = arr('Read Previous Content');
const messages = arr('Filter Approved Messages');
const knowledge = arr('Filter Ready Knowledge');

function up(v){ return (v===undefined||v===null?'':v.toString().trim().toUpperCase()); }
function yes(v){ return ['TRUE','YES','1','ДА','APPROVED','ALLOWED'].indexOf(up(v)) >= 0; }
function isConfidential(r){ return up(r.Confidentiality || r.Confidential || r.Confidentiality_Level) === 'CONFIDENTIAL'; }
function isActive(r){ var s = up(r.Status); return s==='' || s==='ACTIVE' || s==='PUBLISHED' || s==='APPROVED'; }
function isCurrent(r){ var d = (r.Valid_Until || r.Expiry_Date || '').toString().trim(); if(!d) return true; return d.slice(0,10) >= today; }
function nonEmptyRow(r){ if(!r) return false; var ks=Object.keys(r); for(var i=0;i<ks.length;i++){ var k=ks[i]; if(k==='row_number') continue; if((r[k]===undefined||r[k]===null?'':r[k].toString().trim())!=='') return true; } return false; }
function nonEmptyObj(o){ return o && Object.keys(o).length>0; }
function knowOK(r){ return isActive(r) && isCurrent(r) && yes(r.Approved_for_Knowledge); }
function rightsOK(r){ return yes(r.Usage_Rights) && yes(r.Advertising_Rights) && yes(r.AI_Reference_Rights); }
function pubOK(r){ return knowOK(r) && !isConfidential(r) && rightsOK(r); }
function byBrandSku(r){
  var okSku = (r.SKU_ID!==undefined && r.SKU_ID!==null && r.SKU_ID.toString().trim()===skuId && skuId!=='');
  var okBrand = (r.Brand_ID!==undefined && r.Brand_ID!==null && r.Brand_ID.toString().trim()===brandId && brandId!=='');
  return okSku || okBrand;
}
// Filtered Messages/Knowledge: scope to this brand/SKU when tagged; else treat as global.
function relevant(r){
  var hasBrand = (r.Brand_ID!==undefined && r.Brand_ID!==null && r.Brand_ID.toString().trim()!=='');
  var hasSku = (r.SKU_ID!==undefined && r.SKU_ID!==null && r.SKU_ID.toString().trim()!=='');
  if(!hasBrand && !hasSku) return true;
  return byBrandSku(r);
}

const brandObj = brands.filter(function(b){ return b.Brand_ID!==undefined && b.Brand_ID.toString().trim()===brandId; })[0] || {};
const skuObj = skus.filter(function(s){ return s.SKU_ID!==undefined && s.SKU_ID.toString().trim()===skuId; })[0] || {};
const audObj = audiences.filter(function(a){ return a.Audience_ID!==undefined && a.Audience_ID.toString().trim()===audId; })[0] || {};

const brandSkuClaims = claims.filter(nonEmptyRow).filter(byBrandSku);
function claimAllowed(r){ return isActive(r) && !isConfidential(r) && yes(r.Approved_for_Knowledge) && yes(r.Usage_Rights) && yes(r.Advertising_Rights); }
const allowedClaims = brandSkuClaims.filter(claimAllowed);
const forbiddenClaims = brandSkuClaims.filter(function(r){ return !claimAllowed(r); });

const mediaAssets = media.filter(nonEmptyRow).filter(byBrandSku).filter(function(r){ return knowOK(r) && !isConfidential(r) && yes(r.Usage_Rights); });
const prevContent = prev.filter(nonEmptyRow).filter(byBrandSku).filter(knowOK);
const relevantMessages = messages.filter(nonEmptyRow).filter(relevant);
const relevantKnowledge = knowledge.filter(nonEmptyRow).filter(relevant);

// Clean daily task row (drop internal helper fields)
const HELPERS = ['_mode','_today','_timezone','_missing_fields','task_state','dedup_state'];
const dailyTask = {};
Object.keys(task).forEach(function(k){ if(HELPERS.indexOf(k) < 0) dailyTask[k] = task[k]; });

// INTERNAL context — full gated data (never leaves orchestrator boundary; matches BF_02 schema)
const INTERNAL_BRAND_CONTEXT = {
  brand: (nonEmptyObj(brandObj) && knowOK(brandObj)) ? [brandObj] : [],
  messages: relevantMessages,
  knowledge: relevantKnowledge,
  sku: (nonEmptyObj(skuObj) && knowOK(skuObj)) ? skuObj : {},
  allowed_claims: allowedClaims,
  forbidden_claims: forbiddenClaims,
  audience: nonEmptyObj(audObj) ? audObj : {},
  media_assets: mediaAssets,
  previous_content: prevContent
};

// PUBLIC brief — strip confidential fields, only public-eligible rows.
// NOTE: messages/knowledge/rights/internal links are intentionally NOT here — must not reach BF_01 (Gemini).
const STRIP = ['Internal_Price','Cost','Margin','Supplier','Personal_Data','Email','Phone','Rights_Document','Rights_Doc','API_Key','Secret','Unpublished_Promo','Confidential_Notes','Confidentiality','Confidential','Usage_Rights','Advertising_Rights','AI_Reference_Rights'];
function publicSafe(obj){
  var o = {}; var ks = Object.keys(obj || {});
  for (var i=0;i<ks.length;i++){
    var k = ks[i];
    if (STRIP.indexOf(k) >= 0) continue;
    if (/price|cost|margin|secret|api[_-]?key|token|personal|email|phone|rights|supplier|unpublished|confiden/i.test(k)) continue;
    o[k] = obj[k];
  }
  return o;
}
const PUBLIC_RESEARCH_BRIEF = {
  Run_ID: task.Run_ID,
  Task_ID: task.Task_ID,
  Content_Type: task.Content_Type,
  Channel: task.Channel,
  brand: pubOK(brandObj) ? publicSafe(brandObj) : {},
  sku: pubOK(skuObj) ? publicSafe(skuObj) : {},
  claims: allowedClaims.filter(pubOK).map(publicSafe),
  audience: publicSafe(audObj),
  reference_media: mediaAssets.filter(pubOK).map(publicSafe),
  learnings_from_previous: prevContent.filter(pubOK).map(publicSafe)
};

return { json: {
  Run_ID: task.Run_ID,
  Task_ID: task.Task_ID,
  Input_Hash: task.Input_Hash,
  _mode: task._mode,
  daily_task: dailyTask,
  INTERNAL_BRAND_CONTEXT: INTERNAL_BRAND_CONTEXT,
  PUBLIC_RESEARCH_BRIEF: PUBLIC_RESEARCH_BRIEF
} };

const merged = $json;
const ctx = merged.INTERNAL_BRAND_CONTEXT || {};
const dailyTask = merged.daily_task || {};

// Research packet from BF_01 success output (paired via Merge)
let research = {};
try { const r = $('BF_01_RESEARCH_GEMINI').item; if (r && r.json) research = r.json; } catch (e) {}
if (!research || Object.keys(research).length === 0) { research = merged.research_packet || {}; }

const warnings = [];
const internal = {
  brand: ctx.brand || [],
  messages: ctx.messages || [],
  knowledge: ctx.knowledge || [],
  sku: ctx.sku || {},
  allowed_claims: ctx.allowed_claims || [],
  forbidden_claims: ctx.forbidden_claims || [],
  audience: ctx.audience || {},
  media_assets: ctx.media_assets || [],
  previous_content: ctx.previous_content || []
};

if (!internal.brand.length) warnings.push('brand context empty or not knowledge-approved');
if (!internal.sku || Object.keys(internal.sku).length === 0) warnings.push('sku context empty or not knowledge-approved');
if (!internal.allowed_claims.length) warnings.push('no approved claims available for this brand/SKU');
if (!internal.media_assets.length) warnings.push('no rights-cleared media assets found');
if (!research || Object.keys(research).length === 0) warnings.push('research_packet from BF_01 is empty');

// prompt_version / instructions_version are not yet sourced anywhere upstream
const promptVersion = '';
const instructionsVersion = '';
if (!promptVersion) warnings.push('prompt_version not set (needs a source)');
if (!instructionsVersion) warnings.push('instructions_version not set (needs a source)');

return { json: {
  task_id: merged.Task_ID || dailyTask.Task_ID || '',
  run_id: merged.Run_ID || '',
  prompt_version: promptVersion,
  instructions_version: instructionsVersion,
  daily_task: dailyTask,
  internal_brand_context: internal,
  research_packet: research,
  warnings: warnings
} };
